14	/** The due figures of claims, and the due-totals of people, at the rates on a sheet: as they are
15	 *  now, or on any other {@link Basis} (such as the sheet as it stood at the end of an earlier day). */
16	@Service
17	public class Dues {
18	
19	    /** What a sheet's figures are worked out from: its today, its dated settings and its rates. */
20	    public interface Basis {
21	
22	        /** The day that stands in for the sheet's today. */
23	        LocalDate today();
24	
25	        /** The floor in force on a day. */
26	        BigDecimal floor(LocalDate day);
27	
28	        /** The late percent in force on a day. */
29	        BigDecimal latePct(LocalDate day);
30	
31	        /** The cap in force on the basis's today; null when there is none. */
32	        BigDecimal cap();
33	
34	        /** The policy date in force: the one set, or else the basis's today. */
35	        LocalDate policyDateInForce();
36	
37	        /** The rates of a grade, the latest from-date first and the one with none last. */
38	        List<Rate> rates(String grade);
39	    }
40	
41	    private final RateRepository rates;
42	    private final SheetService sheets;
43	
44	    public Dues(RateRepository rates, SheetService sheets) {
45	        this.rates = rates;
46	        this.sheets = sheets;
47	    }
48	
49	    /** The sheet as it is now: its today, its settings and its rates. */
50	    public Basis now(String sheetId) {
51	        return new Basis() {
52	            @Override
53	            public LocalDate today() {
54	                return sheets.today(sheetId);
55	            }
56	
57	            @Override
58	            public BigDecimal floor(LocalDate day) {
59	                return sheets.floor(sheetId, day);
60	            }
61	
62	            @Override
63	            public BigDecimal latePct(LocalDate day) {
64	                return sheets.latePct(sheetId, day);
65	            }
66	
67	            @Override
68	            public BigDecimal cap() {
69	                return sheets.cap(sheetId);
70	            }
71	
72	            @Override
73	            public LocalDate policyDateInForce() {
74	                return sheets.policyDateInForce(sheetId);
75	            }
76	
77	            @Override
78	            public List<Rate> rates(String grade) {
79	                return rates.findLatestFirst(sheetId, grade);
80	            }
81	        };
82	    }
83	
84	    /** The due figure a claim shows and totals: the one fixed when it was settled, or else its
85	     *  {@link #bindable} rate figure with the late charge on that figure on top while it is overdue,
86	     *  at least the sheet's floor in force on the claim's date (a correction has neither); null when
87	     *  there is none. */
88	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
89	        return figure(now(sheetId), person, claim);
90	    }
91	
92	    /** The due figure a claim shows and totals on a basis (see {@link #figure(String, Person, Claim)}). */
93	    public BigDecimal figure(Basis basis, Person person, Claim claim) {
94	        if (claim.getSettledDue() != null) {
95	            return claim.getSettledDue();
96	        }
97	        return floored(basis, claim, bindable(basis, person, claim), claim.getStatus().isOpen());
98	    }
99	
100	    /** The figure a claim would have today as an open claim bound by no statement: its rate figure
101	     *  with the late charge on top while it is overdue, at least the floor in force on its date; null
102	     *  when there is none. */
103	    public BigDecimal openFigure(String sheetId, Person person, Claim claim) {
104	        Basis basis = now(sheetId);
105	        return floored(basis, claim, due(basis, person, claim), true);
106	    }
107	
108	    /** A rate figure with its late charge (taken as open or not) on top, then at least the sheet's
109	     *  floor in force on the claim's date (a correction has no floor); null when the figure is. */
110	    private BigDecimal floored(Basis basis, Claim claim, BigDecimal figure, boolean open) {
111	        if (figure == null) {
112	            return null;
113	        }
114	        BigDecimal charged = figure.add(lateCharge(basis, claim, figure, open));
115	        return claim.isCorrection() ? charged : charged.max(basis.floor(claim.getDate()));
116	    }
117	
118	    /** The rate figure a statement binds a claim to: the one its person's last statement bound it to,
119	     *  or else its live rate figure (a pending claim is not bound by a statement while it is pending);
120	     *  never the late charge, which keeps following the sheet's today, nor the floor, which is applied
121	     *  last. Null when there is none, or when the statement bound it to n/a. */
122	    public BigDecimal bindable(String sheetId, Person person, Claim claim) {
123	        return bindable(now(sheetId), person, claim);
124	    }
125	
126	    /** The rate figure a statement binds a claim to on a basis (see {@link #bindable(String, Person, Claim)}). */
127	    public BigDecimal bindable(Basis basis, Person person, Claim claim) {
128	        if (bound(claim) && (claim.getStatedDue() != null || claim.isStatedNa())) {
129	            return claim.getStatedDue();
130	        }
131	        return due(basis, person, claim);
132	    }
133	
134	    /** Whether a statement binds a claim to n/a: its person's last statement bound it to n/a, or
135	     *  else it has no bound figure and no live due: no rate applies to it on its date (for the
136	     *  person's grade on that date), none ever having been set or the one that would having ended. */
137	    public boolean bindsNa(String sheetId, Person person, Claim claim) {
138	        return bindsNa(now(sheetId), person, claim);
139	    }
140	
141	    /** Whether a statement binds a claim to n/a on a basis (see {@link #bindsNa(String, Person, Claim)}). */
142	    public boolean bindsNa(Basis basis, Person person, Claim claim) {
143	        if (bound(claim) && (claim.getStatedDue() != null || claim.isStatedNa())) {
144	            return claim.isStatedNa();
145	        }
146	        return due(basis, person, claim) == null;
147	    }
148	
149	    /** Whether a claim is bound by its person's last statement now (a pending claim is not). */
150	    private static boolean bound(Claim claim) {
151	        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING;
152	    }
153	
154	    /** The late charge on a claim taken as open (or pending) or not, overdue on the sheet's today (its due-by, fixed when it was
155	     *  made, before today; a correction has none): for each full 30 days it is overdue, the late percent in force on
156	     *  that boundary (its due-by plus 30, 60, 90 ... days) of its figure, rounded to two decimals by the claim's
157	     *  {@link #rounding}, the charges added up (a boundary whose percent is 0.00 adds nothing); 0.00 when it is not overdue. */
158	    private BigDecimal lateCharge(Basis basis, Claim claim, BigDecimal figure, boolean open) {
159	        BigDecimal none = BigDecimal.ZERO.setScale(2);
160	        LocalDate today = basis.today();
161	        if (!open || claim.isCorrection() || claim.isDeferredOn(today)) {
162	            return none;
163	        }
164	        long periods = ChronoUnit.DAYS.between(claim.getDueBy(), today) / 30;
165	        if (periods <= 0) {
166	            return none;
167	        }
168	        RoundingMode rounding = rounding(basis, claim);
169	        BigDecimal charge = none;
170	        for (long n = 1; n <= periods; n++) {
171	            BigDecimal pct = basis.latePct(claim.getDueBy().plusDays(30 * n));
172	            if (pct.signum() != 0) {
173	                charge = charge.add(figure.multiply(pct).movePointLeft(2).setScale(2, rounding));
174	            }
175	        }
176	        return charge;
177	    }
178	
179	    /** Whether a claim of the person counts in the live totals on the sheet's today: it counts, it is
180	     *  not deferred on that day, and it is not an open (or pending) claim, unbound by a statement,
181	     *  dated within one of the person's holds or of a person retired on that day. */
182	    public static boolean countsLive(Person person, Claim claim, LocalDate today) {
183	        return claim.getStatus().counts() && !claim.isDeferredOn(today) && !leftOut(person, claim, today);
184	    }
185	
186	    /** Whether a claim of the person counts in a period's totals: by the status it had at the end of
187	     *  the period's last day (see Claim#statusOn) it counts, and the live rules do not leave it out:
188	     *  it is not deferred on the sheet's today, and it is not a claim open (or pending) now,
189	     *  unbound by a statement, dated within one of the person's holds or of a person retired on the
190	     *  sheet's today. */
191	    public static boolean countsAsOf(Person person, Claim claim, LocalDate end, LocalDate today) {
192	        ClaimStatus then = claim.statusOn(end);
193	        return then != null && then.counts() && !claim.isDeferredOn(today) && !leftOut(person, claim, today);
194	    }
195	
196	    /** Whether the live rules leave a claim of the person out: it is open (or pending) now, unbound
197	     *  by a statement, and dated within one of the person's holds or the person is retired on the
198	     *  sheet's today. */
199	    private static boolean leftOut(Person person, Claim claim, LocalDate today) {
200	        return claim.getStatus().isOpen() && !claim.isStated()
201	                && (person.isHeldOn(claim.getDate()) || person.isRetiredOn(today));
202	    }
203	
204	    /** The claims of a person that count in the live totals on the sheet's today. */
205	    public static List<Claim> live(Person person, List<Claim> theirs, LocalDate today) {
206	        return theirs.stream().filter(c -> countsLive(person, c, today)).toList();
207	    }
208	
209	    /** A person's due-total: the sum of the figures of their claims that count, at most the sheet's
210	     *  cap in force on its today; null (n/a) when their grade on the sheet's today has no rate on it and no counting claim
211	     *  has a figure (one fixed, or a live due at the grade in force on its date). */
212	    public BigDecimal dueTotal(String sheetId, Person person, List<Claim> theirs) {
213	        return dueTotal(now(sheetId), person, theirs);
214	    }
215	
216	    /** A person's due-total on a basis (see {@link #dueTotal(String, Person, List)}). */
217	    public BigDecimal dueTotal(Basis basis, Person person, List<Claim> theirs) {
218	        List<BigDecimal> figures = theirs.stream().filter(c -> c.getStatus().counts())
219	                .map(c -> figure(basis, person, c)).filter(d -> d != null).toList();
220	        LocalDate today = basis.today();
221	        boolean rated = RateRepository.inForce(basis.rates(person.gradeOn(today)), today).isPresent();
222	        if (!rated && figures.isEmpty()) {
223	            return null;
224	        }
225	        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
226	        BigDecimal cap = basis.cap();
227	        return cap == null ? sum : sum.min(cap);
228	    }
229	
230	    /** A claim's live due at the rate, in force on the claim's date, for the person's grade in force
231	     *  on that date: amount
232	     *  times pct divided by 100, rounded to two decimals by the claim's {@link #rounding} (the floor is
233	     *  applied later, see {@link #floored}); null when no rate applies on that date. */
234	    private BigDecimal due(Basis basis, Person person, Claim claim) {
235	        RoundingMode rounding = rounding(basis, claim);
236	        return RateRepository.inForce(basis.rates(person.gradeOn(claim.getDate())), claim.getDate())
237	                .map(Rate::getPct)
238	                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
239	                .orElse(null);
240	    }
241	
242	    /** How a claim's live figures round: half up when the date it rounds by (a correction's is that of
243	     *  the claim it corrects) is before the sheet's policy date, else half to even. */
244	    private RoundingMode rounding(Basis basis, Claim claim) {
245	        return claim.roundsBy().isBefore(basis.policyDateInForce()) ? RoundingMode.HALF_UP
246	                : RoundingMode.HALF_EVEN;
247	    }
248	}
